// GF-Forms schickt EIN JSON pro Anlage. Der Webhook legt den POST-Body unter
// .body ab – hier auf die oberste Ebene heben, damit die Google-Sheets-Node die
// Felder automatisch den gleichnamigen Spalten zuordnen kann.
return $input.all().map((item) => ({ json: item.json.body ?? item.json }));

// Baut die Notion-Properties AUS DEM SHEET – und laesst leere Werte konsequent
// weg. Ein select/multi_select mit leerem Namen laesst Notion nicht zu; genau
// daran ist der alte Flow abgebrochen.
// Es werden ausschliesslich Werte geschrieben, die GF-Forms bereits auf die
// vorhandenen Notion-Optionen abbildet – es entstehen also keine neuen Optionen.

const row = $('Loop Over Items').first().json;
const pageId = $('Seite anlegen').first().json.id;

const t = (v) => (v === undefined || v === null ? '' : String(v).trim());
const props = {};

const sel = (name, v) => { if (t(v)) props[name] = { select: { name: t(v) } }; };
const txt = (name, v) => { if (t(v)) props[name] = { rich_text: [{ text: { content: t(v).slice(0, 1900) } }] }; };
const multi = (name, v) => {
  const names = t(v).split(',').map((s) => s.trim()).filter(Boolean);
  if (names.length) props[name] = { multi_select: names.map((n) => ({ name: n })) };
};

sel('Customer', row['Ihr Unternehmen']);
sel('Status WP-System', row['Status Wärmepumpen-System']);
sel('Status PV-Anlage', row['Status PV-Anlage']);
sel('WP-Konfiguration', row['Wärmepumpen-Konfiguration']);
sel('Commercial Setup', row['Nutzung von PV-Strom in ihrem Gebäude?']);

// In Notion ein MULTI-Select (im alten Flow faelschlich als select geschrieben).
multi('Andere Wärmeerzeuger', row['Andere Wärmeerzeuger ']);

txt('PV-Anlage Konfiguration', row['PV-Anlage Konfiguration ']);
txt('PV-Partner / Umsetzungspartner', row['PV-Partner ']);
txt('GLT/EMS', row['Gibt es ein Gebäudeleittechnik (GLT)-System oder Energiemonitoring/managementsystem (EMS) in ihrem Gebäude?']);
txt('Wärmebedarf', row['Berechnung der Einsparpotenziale (optional)']);

// HINWEIS: 'Contact GF' wird bewusst NICHT gesetzt. Das Feld ist ein select mit
// nur drei Optionen; 'Daniel Lizardo' & Co. wuerden dort neue Optionen anlegen.
// Der Wert steht weiterhin im Sheet und wird vom Filter oben ausgewertet.

return [{ json: { pageId, properties: props } }];

// Ampel Inverter: Serie/Modell gegen die Inverter DB pruefen.
// Mehrere Werte sind mit ', ' getrennt (Multi-Select-Format).
// Zurueckgeschrieben werden NUR Treffer aus der DB -> keine neuen Optionen.

const entries = $input.all();
const row = $('Loop Over Items').first().json;
const pageId = $('Seite anlegen').first().json.id;

const norm = (s) => (s || '').trim().toLowerCase();
const split = (v) => (v || '').split(',').map((s) => s.trim()).filter(Boolean);

const manufacturers = split(row['PV-Wechselrichter Hersteller']);
const seriesList = split(row['PV-Wechselrichter Modell / Serie']);

const AMPEL = { '🟢': '🟢 Grün', '🟡': '🟡 Gelb', '🔴': '🔴 Rot' };
const RANK = { '🟢 Grün': 1, '🟡 Gelb': 2, '🔴 Rot': 3 };
const SKIP_NO_DATA = '⚪ Skipped: no manufacturer/series data';
const SKIP_NOT_FOUND = '⚪ Skipped: device not in Inverter DB';

let ampel = null;
const matchedSeries = [];

if (!manufacturers.length || !seriesList.length) {
  ampel = SKIP_NO_DATA;
} else {
  for (const wanted of seriesList) {
    const hit = entries.find((e) => {
      const series = e.json.property_series || '';
      const models = e.json.property_models || '';
      if (series && norm(series) === norm(wanted)) return true;
      return models.split(',').map((m) => m.trim()).some((m) => norm(m) === norm(wanted));
    });
    if (!hit) continue;
    matchedSeries.push(hit.json.property_series || wanted);
    const a = AMPEL[(hit.json.property_ampel_inverter || '').trim()];
    if (a && (!ampel || RANK[a] > (RANK[ampel] || 0))) ampel = a;
  }
  if (!matchedSeries.length || !ampel) ampel = ampel || SKIP_NOT_FOUND;
}

return [{
  json: {
    pageId,
    inverterAmpel: ampel,
    // Hersteller nur setzen, wenn die Serie in der DB gefunden wurde.
    inverterManufacturers: matchedSeries.length ? [manufacturers[0]] : [],
    inverterSeries: [...new Set(matchedSeries)],
  },
}];

// Ampel Controller + die Geraetefelder in EINEM Rutsch vorbereiten.
// Hersteller/Serie werden nur geschrieben, wenn sie in der Notion-DB existieren
// -> keine neuen Multi-Select-Optionen durch Kunden-Freitext.

const entries = $input.all();
const row = $('Loop Over Items').first().json;
const inv = $('Inverter Ampel zuordnen').first().json;
const pageId = inv.pageId;

const norm = (s) => (s || '').trim().toLowerCase();
const split = (v) => (v || '').split(',').map((s) => s.trim()).filter(Boolean);

const manufacturers = split(row['Hersteller der Wärmepumpe']);
const seriesList = split(row['Wärmepumpen Controller (Modell- oder Serienname, z.B. ISG-Web)']);

const AMPEL = { '🟢': '🟢 Grün', '🟡': '🟡 Gelb', '🔴': '🔴 Rot' };
const RANK = { '🟢 Grün': 1, '🟡 Gelb': 2, '🔴 Rot': 3 };
const SKIP_NO_DATA = '⚪ Skipped: no manufacturer/series data';
const SKIP_NOT_FOUND = '⚪ Skipped: device not in Controller DB';

let ampel = null;
const matchedSeries = [];

if (!manufacturers.length || !seriesList.length) {
  ampel = SKIP_NO_DATA;
} else {
  for (const wanted of seriesList) {
    const hit = entries.find((e) => {
      const series = e.json.property_series || '';
      const models = e.json.property_models || '';
      if (series && norm(series) === norm(wanted)) return true;
      return models.split(',').map((m) => m.trim()).some((m) => norm(m) === norm(wanted));
    });
    if (!hit) continue;
    matchedSeries.push(hit.json.property_series || wanted);
    const a = AMPEL[(hit.json.property_ampel_controller || '').trim()];
    if (a && (!ampel || RANK[a] > (RANK[ampel] || 0))) ampel = a;
  }
  if (!matchedSeries.length || !ampel) ampel = ampel || SKIP_NOT_FOUND;
}

const props = {};
const msel = (name, values) => {
  const list = [...new Set((values || []).filter(Boolean))];
  if (list.length) props[name] = { multi_select: list.map((n) => ({ name: n })) };
};

if (inv.inverterAmpel) props['Ampel Inverter'] = { select: { name: inv.inverterAmpel } };
if (ampel) props['Ampel Controller'] = { select: { name: ampel } };
msel('Inverter manufacturer', inv.inverterManufacturers);
msel('Inverter series', inv.inverterSeries);
msel('HP manufacturer', matchedSeries.length ? [manufacturers[0]] : []);
msel('HP Controller Series', matchedSeries);

return [{
  json: {
    pageId,
    properties: props,
    unternehmen: row['Ihr Unternehmen'] || '',
    adresse: row['Adressen aller Gebäude mit gleichen Eigenschaften'] || '',
    ampelInverter: inv.inverterAmpel || '—',
    ampelController: ampel || '—',
  },
}];

// Ergebnis dieser Anlage einsammeln und zurueck in die Schleife geben.
const r = $('Controller Ampel zuordnen').first().json;
return [{
  json: {
    unternehmen: r.unternehmen,
    adresse: r.adresse,
    ampelInverter: r.ampelInverter,
    ampelController: r.ampelController,
  },
}];
